contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }

    function run(uint256 apr) public {
        require(apr < 2 ** 255);
        InitializeRiskConfigParams memory rc = c.riskConfig();
        require(rc.minTenor > 0 && rc.minTenor < rc.maxTenor);
        uint256 t = rc.minTenor;

        // Before placing a borrow offer, the APR query must revert (null offer)
        bool revertedBefore;
        try c.getBorrowOfferAPR(address(this), t) returns (uint256) {
            revertedBefore = false;
        } catch {
            revertedBefore = true;
        }

        // Place the borrow offer (top-level state-changing call)
        uint256[] memory tenors = new uint256[](1);
        tenors[0] = t;
        int256[] memory aprs = new int256[](1);
        aprs[0] = int256(apr);
        uint256[] memory mults = new uint256[](1);
        mults[0] = 0;
        YieldCurve memory curve = YieldCurve({tenors: tenors, aprs: aprs, marketRateMultipliers: mults});
        c.sellCreditLimit(SellCreditLimitParams({curveRelativeTime: curve}));

        assert(revertedBefore && c.getBorrowOfferAPR(address(this), t) == apr);
    }

    receive() external payable {}
}

