contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }

    function run(address lender, uint256 tenor) public payable {
        require(lender != address(0), "lender must not be zero");

        // Before any offer is placed, querying the loan offer APR must revert (NULL_OFFER)
        bool revertedBefore;
        try c.getLoanOfferAPR(lender, tenor) returns (uint256) {
            revertedBefore = false;
        } catch {
            revertedBefore = true;
        }

        // Place a null loan offer (clears any existing one): maxDueDate 0 and empty curve
        uint256[] memory emptyTenors = new uint256[](0);
        int256[] memory emptyAprs = new int256[](0);
        uint256[] memory emptyMultipliers = new uint256[](0);
        c.buyCreditLimit(
            BuyCreditLimitParams({
                maxDueDate: 0,
                curveRelativeTime: YieldCurve(emptyTenors, emptyAprs, emptyMultipliers)
            })
        );

        // After the null offer, the loan offer is null, so querying the APR must still revert
        bool revertedAfter;
        try c.getLoanOfferAPR(lender, tenor) returns (uint256) {
            revertedAfter = false;
        } catch {
            revertedAfter = true;
        }

        assert(revertedBefore && revertedAfter);
    }

    receive() external payable {}
}

