contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }

    function run(
        address owner,
        uint256 swapFeeAPR,
        uint256 fragmentationFee,
        uint256 liquidationRewardPercent,
        uint256 overdueCollateralProtocolPercent,
        uint256 collateralProtocolPercent,
        uint256 crOpening,
        uint256 crLiquidation,
        uint256 minimumCreditBorrowAToken,
        uint256 minTenor,
        uint256 maxTenor
    ) public {
        require(owner != address(0));
        require(overdueCollateralProtocolPercent <= 1e18 && collateralProtocolPercent <= 1e18);
        require(crOpening >= 1e18 && crLiquidation >= 1e18 && crOpening > crLiquidation);
        require(minimumCreditBorrowAToken > 0);
        require(minTenor > 0 && maxTenor > minTenor);

        InitializeFeeConfigParams memory f = InitializeFeeConfigParams({
            swapFeeAPR: swapFeeAPR,
            fragmentationFee: fragmentationFee,
            liquidationRewardPercent: liquidationRewardPercent,
            overdueCollateralProtocolPercent: overdueCollateralProtocolPercent,
            collateralProtocolPercent: collateralProtocolPercent,
            feeRecipient: address(this)
        });
        InitializeRiskConfigParams memory r = InitializeRiskConfigParams({
            crOpening: crOpening,
            crLiquidation: crLiquidation,
            minimumCreditBorrowAToken: minimumCreditBorrowAToken,
            borrowATokenCap: type(uint256).max,
            minTenor: minTenor,
            maxTenor: maxTenor
        });
        InitializeOracleParams memory o = InitializeOracleParams({
            priceFeed: address(this),
            variablePoolBorrowRateStaleRateInterval: 1 days
        });
        InitializeDataParams memory d = InitializeDataParams({
            weth: address(this),
            underlyingCollateralToken: address(this),
            underlyingBorrowToken: address(this),
            variablePool: address(this)
        });

        c.initialize(owner, f, r, o, d);

        assert(
            c.hasRole(bytes32(0), owner)
            && c.hasRole(keccak256("PAUSER_ROLE"), owner)
            && c.hasRole(keccak256("KEEPER_ROLE"), owner)
            && c.hasRole(keccak256("BORROW_RATE_UPDATER_ROLE"), owner)
            && !c.hasRole(bytes32(0), address(this))
            && !c.hasRole(keccak256("PAUSER_ROLE"), address(this))
        );
    }

    fallback(bytes calldata input) external returns (bytes memory) {
        if (input.length >= 4) {
            bytes4 sig = bytes4(input);
            if (sig == IPriceFeed.getPrice.selector) {
                return abi.encode(int256(1e18));
            }
            if (sig == IERC20Metadata.decimals.selector) {
                return abi.encode(uint256(18));
            }
            if (sig == IERC20Metadata.name.selector || sig == IERC20Metadata.symbol.selector) {
                return abi.encode(uint256(0x20), uint256(0), uint256(0));
            }
        }
        return abi.encode(int256(1e18));
    }

    receive() external payable {}
}

