    function run(uint256 positionId) public {
        bool isDebt = c.isDebtPositionId(positionId);
        bool isCredit = c.isCreditPositionId(positionId);
        bool reverted;
        if (!isDebt && !isCredit) {
            try c.getLoanStatus(positionId) returns (LoanStatus) {
                reverted = false;
            } catch {
                reverted = true;
            }
        } else {
